import os,re
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))
inp,out=G['Demo pair 1 input'],G['Demo pair 1 output']
def f(g):
    zs=[(i,j) for i,row in enumerate(g) for j,v in enumerate(row) if v==0]
    rs=sorted({i for i,j in zs}); cs=sorted({j for i,j in zs})
    o=[row[:] for row in g]
    for i in rs: o[i]=[0]*len(g[0])
    for j in cs:
        for i in range(len(g)): o[i][j]=0
    for i in range(len(g)):
        for j in range(len(g[0])):
            if g[i][j]==2: o[i][j]=2
    return o
print(f(inp)==out)
